    print("params:", data['params'])
    # check what the actual records look like
    for k in data:
        if k != 'params':
            print(f"\nKey '{k}': type={type(data[k])}")
            if isinstance(data[k], list):
                print(f"  {len(data[k])} records")
                print(f"  first record: {data[k][0]}")
            elif isinstance(data[k], dict):
                print(f"  subkeys: {list(data[k].keys())[:5]}")
